import{_ as i,l as o,o as t,c as n,v as e,p as l,x as r,d as m,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Bates 跳扩散","description":"","frontmatter":{"title":"Bates 跳扩散","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bates.md","filePath":"quant/bates.md","lastUpdated":1789023840000}'),p={name:"quant/bates.md"};function u(B,a,_,c,E,b){const s=o("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="bates-跳扩散" tabindex="-1">Bates 跳扩散 <a class="header-anchor" href="#bates-跳扩散" aria-label="Permalink to &quot;Bates 跳扩散&quot;">​</a></h1><div class="epigraph"><p>把对数正态跳跃叠在随机波动之上，短到期的偏斜由跳强度与跳幅度解释，中长到期的弯曲与期限结构仍由方差的均值回复承担。</p><footer>—— Bates, Jumps and Stochastic Volatility: Exchange Rate Processes Implicit in Deutsche Mark Options, Review of Financial Studies, 1996</footer></div><p><a href="/quant/heston">Heston</a> 的纯扩散难以同时拟合极短到期的陡峭偏斜：要在几天内把左尾撑开，只能把 vol-of-vol 抬到破坏 Feller、也破坏长端的程度。David Bates 1996 年在马克外汇期权上把 Heston 的平方根方差与 Merton 式复合泊松跳跃写在同一个仿射框架里：价格连续部分仍与方差相关，偶尔再乘一个对数正态跳。特征函数是二者的乘积，欧式定价路径与 <a href="/quant/heston-cf">Heston 特征函数</a> 相同，只多一段整函数。本篇写这一结合的机制与校准分工，纯跳见 <a href="/quant/merton-jump">Merton 跳扩散</a>，不把 1993 年的五参数模型再讲一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>外汇与股权的短端微笑在 1990 年代已经陡到扩散解释吃力。跳跃能在任意短的区间内把质量移到远处，隐含波动的短端偏斜几乎不随 \\(\\sqrt{T}\\) 消失；随机波动则生成波动聚类、杠杆与微笑的期限衰减。只用跳，独立增量让长到期由中心极限定理拉回，ATM 期限结构与波动的波动无法刻画；只用随机波动，短端要靠瞬时方差的剧烈扩散，参数在期限之间冲突。问题是：在仿射约束下同时保留 CIR 方差与有限活动跳，使特征函数仍然闭合，从而用一份欧式曲面校准两套机制。</p><p>Bates 的经验对象是马克期权：外汇的跳可以是双向的，股票指数后来更常把跳做成负向不对称。模型形式通用，符号惯例与哪些矩被跳承担随市场而变，不应把外汇校准表直接贴到股指上。</p><h3 id="为何必须是仿射跳而不是任意跳" tabindex="-1">为何必须是仿射跳而不是任意跳 <a class="header-anchor" href="#为何必须是仿射跳而不是任意跳" aria-label="Permalink to &quot;为何必须是仿射跳而不是任意跳&quot;">​</a></h3><p>任意跳幅度配任意随机波动，欧式又回到二维积分或 MC。仿射跳扩散要求：强度至多对状态仿射（Bates 原文用常数强度），跳矩生成函数存在，且与连续部分的 Riccati 耦合方式简单。对数正态跳的矩母函数是指数二次，与 Heston 的 \\(C,D\\) 相乘即可。Kou 的双指数、方差伽马的无穷活动，要另写 Lévy 部分；Bates（1996）指定的是有限次、对数正态的泊松跳，不要把后续的 SVJ 变体都算进这一篇论文。</p><p><span class="marginnote">「跳扩散」在谈话里常泛指一切带不连续的模型。Bates 是 Heston 加 Merton 跳这一具体仿射规格。强度随方差变（state-dependent intensity）是更晚的扩展，原文没有用它来拟合马克。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>风险中性下，</p> \\[\\frac{\\mathrm{d}S_t}{S_{t-}}=(r-q-\\lambda\\bar{k})\\,\\mathrm{d}t+\\sqrt{v_t}\\,\\mathrm{d}W^S_t+(J-1)\\,\\mathrm{d}N_t, \\]\\[\\mathrm{d}v_t=\\kappa(\\theta-v_t)\\,\\mathrm{d}t+\\sigma\\sqrt{v_t}\\,\\mathrm{d}W^v_t,\\qquad \\mathrm{d}W^S\\mathrm{d}W^v=\\rho\\,\\mathrm{d}t, \\]<p>\\(N\\) 是强度 \\(\\lambda\\) 的泊松过程，\\(J\\) 独立、\\(\\ln J\\sim\\mathcal{N}(\\mu_J,\\delta^2)\\)，\\(\\bar{k}=\\mathrm{e}^{\\mu_J+\\delta^2/2}-1\\) 是补偿，使贴现资产仍为鞅。特征函数</p> \\[\\phi_{\\mathrm{Bates}}(u)=\\phi_{\\mathrm{Heston}}(u)\\exp\\bigl(\\lambda T(\\psi_J(u)-1-iu\\bar{k})\\bigr), \\]<p>其中 \\(\\psi_J(u)=\\exp(iu\\mu_J-\\tfrac12\\delta^2 u^2)\\) 为一次跳的特征函数，\\(\\phi_{\\mathrm{Heston}}\\) 用同一套 \\(C,D\\)（注意连续部分的漂移已含补偿）。欧式价格仍走傅里叶反演；分支跟踪只作用于 Heston 段，跳因子在实轴上整且不引入新的对数切割。</p><h3 id="参数如何分担微笑" tabindex="-1">参数如何分担微笑 <a class="header-anchor" href="#参数如何分担微笑" aria-label="Permalink to &quot;参数如何分担微笑&quot;">​</a></h3><p>\\(\\lambda,\\mu_J,\\delta\\) 主要打短端：\\(\\lambda\\) 管跳来得有多勤，\\(\\mu_J\\lt 0\\) 管左偏，\\(\\delta\\) 管跳本身的宽度因而影响翼部。Heston 的 \\(v_0,\\theta,\\kappa,\\sigma,\\rho\\) 管从数周到数年的水平、衰减、弯曲与杠杆。识别上跳与 vol-of-vol 在中等期限竞争：两者都能加峰度。实务校准常先用短到期切片稳住跳，再在中长端放随机波动，或对 \\(\\lambda\\) 加惩罚以免把一切峰度都解释成天天跳。外汇上 \\(\\mu_J\\) 可接近零而 \\(\\delta\\) 显著；股指上更常见负均值跳配中等 \\(\\lambda\\)。</p><p>风险溢价可以写在 \\(\\lambda\\) 与方差漂移上，物理测度与定价测度的跳强度不同。Bates 估计的是期权隐含过程，不能直接拿去当历史跳频率的检验；历史跳见 <a href="/quant/jump-tests">跳跃检验</a>，那是二次变差分解，不是同一套参数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>瞬时收益的二次变差分成 \\(\\int v\\) 与 \\(\\sum(\\ln J)^2\\)。短区间内若发生一次跳，二次变差的跳部分占主导，期权短端表现得像 Merton；若没有跳，路径像 Heston。微笑的期限结构因此是「跳的 \\(1/T\\) 贡献」与「随机方差的均值回复」的叠加。杠杆 \\(\\rho\\) 仍通过连续部分工作：没有跳的路径上，跌势伴随方差上升。跳与连续杠杆不要重复解释同一偏斜——校准若同时给很大的负 \\(\\mu_J\\) 和很负的 \\(\\rho\\)，短端会被拟合两次，样本外容易一边过陡。</p><p>相对局部波动，Bates 的远期微笑仍能打开，因为方差是状态变量；相对纯 Heston，短端不再强迫 \\(\\sigma\\) 极端。相对纯 Merton，波动可以聚类：跳之后若 \\(v\\) 并不自动升高（原文跳只打在 \\(S\\) 上，不打在 \\(v\\) 上），「跳后波动升」要靠后续扩展（同时跳方差）或靠相关扩散去慢慢抬 \\(v\\)。这是读 1996 年规格时必须守住的边界：跳在现货，不在方差。</p>',21)),(t(),l(h,null,{default:r(()=>[d(s,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22Heston%20%E8%BF%9E%E7%BB%AD%E9%83%A8%E5%88%86%22%5D%20--%3E%20PhiH%5B%22%CF%86_Heston%22%5D%0A%20%20J%5B%22%E5%A4%8D%E5%90%88%E6%B3%8A%E6%9D%BE%E5%AF%B9%E6%95%B0%E6%AD%A3%E6%80%81%E8%B7%B3%22%5D%20--%3E%20PhiJ%5B%22%E8%B7%B3%E5%9B%A0%E5%AD%90%20exp(%CE%BBT(%CF%88-1))%22%5D%0A%20%20PhiH%20--%3E%20Phi%5B%22%CF%86_Bates%22%5D%0A%20%20PhiJ%20--%3E%20Phi%0A%20%20Phi%20--%3E%20Eur%5B%22%E5%82%85%E9%87%8C%E5%8F%B6%E6%AC%A7%E5%BC%8F%E4%BB%B7%22%5D%0A%20%20Eur%20--%3E%20Short%5B%22%E7%9F%AD%E7%AB%AF%E5%81%8F%E6%96%9C%3A%20%E8%B7%B3%22%5D%0A%20%20Eur%20--%3E%20Long%5B%22%E4%B8%AD%E9%95%BF%E7%AB%AF%3A%20%E9%9A%8F%E6%9C%BA%E6%96%B9%E5%B7%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="模拟与欧式对账" tabindex="-1">模拟与欧式对账 <a class="header-anchor" href="#模拟与欧式对账" aria-label="Permalink to &quot;模拟与欧式对账&quot;">​</a></h3><p>MC 路径要同时离散 CIR 与泊松跳：在一步内先扩散再按 \\(\\mathrm{Poisson}(\\lambda\\Delta t)\\) 抽跳次数，或用指数等待时间。欧式应用特征函数对账，不要只用 MC 给香草定价。障碍与触及对跳敏感——路径可以越过障碍而不经过中间值——布朗桥公式失效，必须按跳后位置判断敲入，这与 <a href="/quant/is-barrier">障碍重要性采样</a> 的扩散假设冲突。控制变量仍可用 Bates 欧式闭式。</p><p><span class="marginnote">补偿项 \\(-\\lambda\\bar{k}\\) 漏写一次，远期就不再是 \\(S\\mathrm{e}^{(r-q)T}\\)，全部虚值价格系统性偏。这是跳扩散实现里比 Riccati 更常见的错误。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>有限活动意味着任意短区间内「不跳」的概率为正，短端微笑再陡也仍是泊松式的稀疏大跳，不是 VG/CGMY 那种无穷小跳堆积。若市场短端翼部要的是无穷活动，Bates 会把 \\(\\lambda\\) 与 \\(\\delta\\) 推向不真实的天天大跳。校准参数的时间序列若 \\(\\lambda\\) 剧烈跳动，说明模型在用跳强度当垃圾桶吸收事件风险，而不是一个稳定的风险中性律。</p><p>美式、障碍、离散股利要数值方法；特征函数只管欧式。多资产篮子的共跳没有被 1996 年单资产外汇模型给出。Bates 提供的是仿射 SVJ 的一条标准规格与外汇上的实证，不是「所有带跳的 Heston」的总称。后续 Duffie–Pan–Singleton 的一般仿射跳、同时跳方差、随机强度，应单独引用。</p><p><span class="marginnote">把 Bates 的 \\(\\lambda\\) 理解成「每年预期崩盘次数」是叙事，不是估计量的含义。风险中性强度含溢价，通常大于物理测度下数得到的跳频。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bates（1996）在 Heston 上叠加补偿后的对数正态复合泊松跳，特征函数为二者乘积，欧式仍傅里叶反演。</li><li>跳主要解释短端偏斜与峰度，CIR 方差解释期限结构与波动聚类；二者在中等期限识别上竞争。</li><li>原文的跳打在现货，不打在方差；跳后瞬时 \\(v\\) 不自动跃升。</li><li>模拟须处理越过障碍；补偿漏写会破坏远期。</li><li>有限活动无法替代无穷活动 Lévy；参数天天改 \\(\\lambda\\) 说明事件风险未被结构化。</li><li>出处：Bates, <em>Review of Financial Studies</em>, 1996；连续部分见 Heston, <em>RFS</em>, 1993；跳的欧式混合见 Merton, <em>JFE</em>, 1976。</li></ul>',9))])}const q=i(p,[["render",u]]);export{f as __pageData,q as default};
